import { readFileSync } from 'fs';
import { resolve } from 'path';

const levelsDir = 'data/levels';
const levels = ['level_25', 'level_31', 'level_43', 'level_54'];

function testParams(W, H, fx, fy) {
  let totalCards = 0;
  let matches = 0;
  const mismatches = [];

  for (const lvl of levels) {
    const data = JSON.parse(readFileSync(levelsDir + '/' + lvl + '.json', 'utf-8'));
    const cards = data.cards;

    const coveredBy = new Map();
    for (const c of cards) coveredBy.set(c.id, new Set());

    for (let i = 0; i < cards.length; i++) {
      for (let j = 0; j < cards.length; j++) {
        if (i === j) continue;
        const a = cards[i];
        const b = cards[j];
        if (a.depth <= b.depth) continue;

        const radA = (a.angle || 0) * (Math.PI / 180);
        const radB = (b.angle || 0) * (Math.PI / 180);
        const effWA = W * Math.abs(Math.cos(radA)) + H * Math.abs(Math.sin(radA));
        const effHA = W * Math.abs(Math.sin(radA)) + H * Math.abs(Math.cos(radA));
        const effWB = W * Math.abs(Math.cos(radB)) + H * Math.abs(Math.sin(radB));
        const effHB = W * Math.abs(Math.sin(radB)) + H * Math.abs(Math.cos(radB));

        const maxDistX = ((effWA + effWB) / 2) * fx;
        const maxDistY = ((effHA + effHB) / 2) * fy;

        if (Math.abs(a.x - b.x) < maxDistX && Math.abs(a.y - b.y) < maxDistY) {
          coveredBy.get(b.id).add(a.id);
        }
      }
    }

    for (const c of cards) {
      totalCards++;
      const expectedFaceUp = c.faceUp ?? false;
      const isCovered = coveredBy.get(c.id).size > 0;
      const computedFaceUp = !isCovered;
      if (expectedFaceUp === computedFaceUp) {
        matches++;
      } else {
        mismatches.push({ lvl, id: c.id, x: c.x, y: c.y, depth: c.depth, expectedFaceUp, computedFaceUp, coveredByCount: coveredBy.get(c.id).size, coveredBy: Array.from(coveredBy.get(c.id)) });
      }
    }
  }

  return { totalCards, matches, mismatches };
}

